// Short label: "Emergency Department (L01)"
export function getDeviceLabel(deviceId) {
  const d = DEVICE_MAP[deviceId];
  if (!d) return deviceId;
  return `${d.dept} (${d.level})`;
}

// Area label: "General Area · L01"
export function getDeviceArea(deviceId) {
  const d = DEVICE_MAP[deviceId];
  if (!d) return null;
  return `${d.area} · ${d.level}`;
}

// Full tooltip: "AHU-L1-ED-01 · Emergency Department · General Area · L01"
export function getDeviceDetail(deviceId) {
  const d = DEVICE_MAP[deviceId];
  if (!d) return deviceId;
  return `${d.ahu} · ${d.dept} · ${d.area} · ${d.level}`;
}

// Returns true if the device has a confirmed mapping
export function isMapped(deviceId) {
  return !!DEVICE_MAP[deviceId];
}